// The `herdr` module: what a mod may ask of Herdr and the user's machine.
// Generated by Herdr; do not edit.

export interface ExecResult {
  code: number;
  stdout: string;
  stderr: string;
}

/** Runs a program with the user's real environment (HOME, PATH, auth). 30 s limit, 8 MiB output.
 *  `on`: on that machine (a space's `machine`) through herdr-core, its home by default.
 *  Rejects when it can't start (not installed, no such folder, the machine is unreachable). */
export function exec(command: string, args?: string[], options?: { cwd?: string; on?: string | null }): Promise<ExecResult>;

/** Runs `hc` (herdr-core) with the given arguments. Add "--json" for machine output. */
export function hc(args: string[]): Promise<ExecResult>;

/** The user's home directory. */
export function home(): string;
/** The app's folder (`~/.config/herdr-app`, or `$HERDR_APP_HOME`): settings.json, keys.json, layouts/. */
export function appHome(): string;

/** Reads UTF-8 text (up to 1 MiB), or null if absent. Runs off the UI thread.
 *  `on`: from that machine (a space's `machine`). */
export function readTextFile(path: string, options?: { on?: string | null }): Promise<string | null>;
/** Writes UTF-8 text only if it still matches expected (null creates a new file).
 * Rejects on a stale snapshot; existing files are replaced atomically. */
export function writeTextFile(path: string, text: string, expected: string | null): Promise<null>;

/** The agents people can start from a menu (entries with `run` in programs.json), most picked
 *  first, and whether each is installed: asked of the shell agents start in (on another machine,
 *  `on`, its login/interactive shell when supported), at most once a minute per machine.
 *  Start one with its `run` as `argv`. */
export function knownAgents(options?: { on?: string | null }): Promise<(Program & { run: string[]; installed: boolean })[]>;

/** Opens the system's folder picker (this machine). Resolves with the chosen folder, or null
 *  when the person cancels. `prompt`: the confirm button's text (default "Open"). */
export function pickFolder(options?: { prompt?: string }): Promise<string | null>;

/** Plays "done" or "blocked" (the attention sounds, or the files settings.json names), or an MP3
 *  file (absolute, or relative to ~/.config/herdr-app). */
export function playSound(sound: string): null;

/**
 * Runs a command, the same ones keys.json binds (`herdr-app commands` lists them all with their
 * arguments). Structural commands fail while their machine's layout is unavailable.
 * Mod props are stored as given, never machine-qualified. Most commands apply right after
 * the call returns; terminal.keep/park finish in the background and toast on failure.
 * A rename without a name is asked for;
 * "" gives the space or tab Herdr's automatic name again. The main ones:
 * Spaces: space.new {name?, folder?, tab?, argv?, task?, machine?}, space.close {id?}, space.rename {id?, name},
 *   space.move {id, index}, space.select {index | id}, space.next, space.prev.
 * Tabs: tab.new {name?, space?, folder?, argv?, task?} (argv: an agent, task: its first message)
 *   or {name?, space?, mod, props?} (a tab whose only pane is a mod),
 *   tab.close {id?}, tab.rename {id?, name}, tab.move {id, index}, tab.select {index | id},
 *   tab.next, tab.prev.
 * Panes: pane.split {direction: "right" | "down", pane?}, pane.close {pane?}, pane.zoom {pane?},
 *   pane.focus {pane | terminal}, pane.go {direction}, pane.swap {direction}. Pane menus get target { pane, terminal }.
 * Terminals: terminal.open {argv?, folder?, place?: "tab" | "right" | "down"}, terminal.kill {terminal},
 *   terminal.keep {terminal, place?} (a running one without a pane, e.g. a sub-agent, gets one),
 *   terminal.park {terminal} (its pane goes, it keeps running; the menu's "Send back"),
 *   terminal.peek {terminal} (peek over the tab, with keep-as-tab and close),
 *   terminal.show {terminal?, pane?} (shown in the pane for now, in place of its own), terminal.copy, terminal.paste,
 *   terminal.right_click {to: "program" | "menu", terminal?} (right-clicks to a program that takes the mouse; Shift: the menu).
 * Agents: agent.next, agent.prev (the agents list's order), agent.focus {terminal} (sub-agents too).
 * Layout (the shown layout's nodes by id): layout.toggle|show|hide {id}, layout.resize {id, px | weight},
 *   layout.select {stack, child}, layout.set {layout} (personal trees; shipped layouts: click/look fields only), layout.switch {name?} (no name: the next one).
 *   layout.clone {name, as?} duplicates and switches; mod.clone {name, as?} duplicates a mod.
 *   Layout clones copy the look and clicks as-is. Layout looks win; settings fill unset fields; theme picks override both.
 *   Mod clones rewrite their own asset prefixes and self-opening overlay names.
 *   Default clone name: <name>-copy; an existing name is refused. Clones record cloned_from: {name, version}.
 *   Shipped layouts/mods are replaced at start; edits move to <name>-edited.
 *   Herdr (main) inherits settings; Herdr 98 and Terminals bring their own look. Clone to change shipped looks beyond theme picks.
 *   layout.reset {name?} resets a shipped layout and its clicks.
 * App: mod.open {name}, overlay.close {id?}, app.help, app.reset, app.theme {name}, app.zoom_in|zoom_out|zoom_reset.
 * Mods: "<mod>.<command>" delivers <command> to that mod's nextCommand().
 */
export function run(name: string, args?: Record<string, unknown>): null;

export type Status = "working" | "blocked" | "done" | "idle";

/** A named piece of work in a space: shared through that machine's core doc.
 * Remote space/tab/pane ids have a machine/ prefix; labels on that machine omit it.
 * Selection, focus, zoom and settled state belong to this screen only. */
export interface TabInfo {
  id: string;
  /** Position in its space, from 1. */
  index: number;
  /** Its name, or its position ("2") when nobody named it. */
  name: string;
  /** Someone named it (tab.rename, tab.new {name}). */
  named: boolean;
  /** The one its space shows. */
  active: boolean;
  /** Most urgent agent status in it, or null. */
  status: Status | null;
  panes: number;
  zoomed: boolean;
  /** Put away on this screen (tab.settle): lists hide it or fold it; it keeps running and comes back
   *  when shown or when an agent in it needs the person. */
  settled: boolean;
  /** ms since the epoch, or null. */
  settled_at: number | null;
  /** When something in it last changed state (null: nothing since the app started). */
  changed_at: number | null;
  /** Since when an agent in it has been working, or null. */
  working_since: number | null;
}

export interface SpaceInfo {
  id: string;
  index: number;
  /** Its name, or where its first terminal is now (repo, else folder, "~" at home)
   *  when nobody named it. */
  name: string;
  /** Someone named it (space.rename, space.new {name}). */
  named: boolean;
  /** Where its new terminals start (on its machine; empty: that machine's home). */
  folder: string;
  /** The machine it lives on (`hc machine ls`), null for this one. */
  machine: string | null;
  /** The git branch of the terminal it shows first, if any. */
  branch: string | null;
  /** The shown space. */
  active: boolean;
  /** Most urgent agent status in it (blocked > done > working > idle), or null. */
  status: Status | null;
  tabs: TabInfo[];
}

/** Machines' layout documents on this connection. Null names this computer.
 * Loading ends after the first read, including failures; unavailable includes offline cores. */
export function machines(): { name: string | null; layout: "loading" | "ready" | "unavailable" }[];

/** Spaces in order. Mods re-render when they change. */
export function spaces(): SpaceInfo[];

/** How a terminal shows, from the app's program table (programs.json): the agent's own
 *  report, else the program it runs. Draw `icon` with `svg(icon)` in a color when `tint`
 *  (a one-color glyph), else `image(icon)`. `tile` / `color`: a colored tile with the glyph
 *  on it, for layouts that want one. */
export interface Program {
  /** The table's key, e.g. "claude", "nvim", "shell", "program" (not listed), "agent". */
  key: string;
  /** For people: "Claude Code", "Neovim", "zsh", or the process name. */
  name: string;
  /** A path in the home folder, e.g. "icons/nvim.svg". */
  icon: string | null;
  tint: boolean;
  tile: string | null;
  color: string | null;
  shell: boolean;
  agent: boolean;
}

export interface AgentInfo {
  address: string;
  pane: string;
  space: string;
  space_name: string;
  tab: string;
  tab_index: number;
  tab_name: string;
  /** "done" means it finished while you weren't looking; it becomes "idle" once you look
   *  (here or on another Herdr client). */
  status: Status;
  /** What the agent reported (OSC 7501 `app`), e.g. "claude-code", "pi", "codex". */
  app: string | null;
  program: Program;
  /** The terminal's title. */
  title: string;
  /** Higher = changed more recently. */
  seq: number;
  /** Pinned with `terminal.pin`, on any Herdr client. */
  pinned: boolean;
  focused: boolean;
}

/** Terminals whose program reports a status (agents), in space, tab, pane order. Live. */
export function agents(): AgentInfo[];

export interface PaneInfo {
  pane: string;
  /** null for a mod pane (`pane.split {mod}`): then `mod` names it, and only
   *  pane, mod, tab, title, focused and zoomed are set. */
  terminal: string | null;
  mod?: string;
  tab: string;
  /** The terminal's title (what the program set), or the mod's name. */
  title: string;
  /** Its live folder, and the git branch there. */
  cwd: string | null;
  branch: string | null;
  /** Agent status if the program reports one, else null. */
  status: Status | null;
  app: string | null;
  program: Program;
  focused: boolean;
  zoomed: boolean;
  /** The app's top-center grip can rearrange this pane. False when zoomed or alone. */
  movable: boolean;
}

/** Every pane in every tab. A pane header mod finds its own with
 *  `panes().find((p) => p.pane === props().pane)`. Live. */
export function panes(): PaneInfo[];

/** Sets agent.next / agent.prev order to match the list a mod displays.
 *  Call when rendering the list. In memory only; missing agents are ignored, new agents
 *  are appended in model order. Without a supplied order, navigation uses model order. */
export function setAgentOrder(addresses: string[]): null;

/** Every core terminal as `hc ls --json` describes it (address, argv, name, template, parent,
 *  labels, state, ...), with `status` as a plain word, the agent's report in `report`, and
 *  `program` (see Program). Live. */
export function terminals(): any[];

/** Actual terminal/pane focus. `space` and `tab` are the current window context.
 *  Clicking a visible layout terminal block, or pane.focus {terminal}, focuses that block:
 *  `terminal` and `cwd` describe it; `pane` and `shown` are null, not its source pane.
 *  Implicit pane split/close/zoom/go/swap and terminal.show fail in that case, as do
 *  terminal.open/keep with place right/down. An explicit pane id targets a model pane.
 *  pane.focus {terminal} prefers the first visible layout terminal block, then a model pane.
 *  `shown`: terminal.show replacement, if any. `agent`: the agent an agent block shows.
 *  `terminal` is null for mod panes. Live. */
export function focused(): { space: string; tab: string; pane: string | null; terminal: string | null; shown: string | null; agent: string | null; cwd: string | null } | null;

/** The shown layout (layouts/<name>.json). Its name is shared("layout").
 *  Root `terminal_menu?: string` chooses a terminal right-click menu mod (default: "menu").
 *  Unknown names warn and fall back to "menu". This replaces the menu, not its items.
 *  Opens a pointer popup with mod.json overlay width/height (default 220×260). */
export function layout(): unknown;

/** The names of every layout in layouts/ (main first). */
export function layouts(): string[];

/** Every command the app runs: its name, arguments and what it does (as `herdr-app commands`).
 *  Mods' own `<mod>.<command>`s aren't listed. */
export function commands(): { name: string; args: { name: string; required: boolean }[]; about: string }[];

/** The window, for layouts that draw their own title bar (`"titlebar": "none"`). `buttons`:
 *  the system draws no window buttons, so draw them (`window.minimize`, `window.maximize`,
 *  `window.close`); on macOS the traffic lights always stay. Live. */
export function window(): {
  platform: "linux" | "macos" | "windows";
  titlebar: "system" | "none";
  buttons: boolean;
  maximized: boolean;
  fullscreen: boolean;
  active: boolean;
};

/** For a floating mod: where it sits now. `vertical` on the left/right edges, horizontal on
 *  top/bottom; while dragged, where it would land. `hovered` is true while the pointer is on it
 *  (or it's dragged); a `peek` drawer is open then. Null for mods that don't float. */
export function placement(): {
  edge: "top" | "right" | "bottom" | "left";
  align: "start" | "center" | "end";
  vertical: boolean;
  hovered: boolean;
  dragging: boolean;
} | null;

/** Every theme color by name: background (the terminals'), surface, canvas (behind cards),
 *  chrome (sidebars and bars), popover, raised, hover, selected, border, input, foreground,
 *  muted, dim, accent, accent_foreground, solid and solid_foreground (a primary button: ink on
 *  paper, paper on ink), selection, working, blocked, done, idle, unknown, ansi0..ansi15.
 *  Light and dark themes name the same colors, so a mod that uses them follows both. */
export function theme(): Record<string, string>;

/** Every theme `app.theme` can use (presets, then `themes/*.json`), each with its colors and
 *  whether it's light. */
export function themes(): { name: string; light: boolean; colors: Record<string, string> }[];

/** The font families on this machine, by name. */
export function fonts(): string[];

/** Herdr's and herdr-core's versions and what's waiting. `app.updates`: false for a build from
 *  source (it never updates). `core.managed`: the package manager that owns the core (homebrew,
 *  nix, mise), which the app never updates. `checked`: unix seconds of the last successful
 *  check; null before success or after a failed check.
 *  `checks`: anything is checked at all (not in a build from source); `checking`: looking now
 *  (`app.check_updates` starts a look). */
export function updates(): {
  app: { version: string; ready: string | null; updates: boolean };
  notes: { version: string; date: string; items: { headline: string; detail: string; fixed: boolean; media: { path: string; width: number; height: number }[] }[]; spotlight: boolean }[];
  core: { version: string | null; managed: string | null; ready: string | null; updating: boolean; error: string | null };
  checked: number | null;
  checks: boolean;
  checking: boolean;
};

/** Record only spotlight versions actually shown expanded, never collapsed headlines. */
export function presentUpdateNotes(versions: string[]): null;

/** Anonymous usage data (one report per day, never terminal content). `enabled`: collecting now;
 *  `setting`: settings.json's `telemetry`; `off_because`: an env var that turns it off for this run
 *  (DO_NOT_TRACK, HERDR_TELEMETRY, CI); `sends`: false for a build from source (it never sends).
 *  `draft`: today's report so far; `queued`: finished days waiting to go, exactly as they'll be
 *  sent; `last_sent`: the last one the server took (`at`: unix seconds). Null until it starts. */
export function telemetry(): {
  enabled: boolean;
  setting: boolean;
  off_because: string | null;
  sends: boolean;
  endpoint: string;
  draft: Record<string, unknown> | null;
  queued: Record<string, unknown>[];
  last_sent: { at: number; report: Record<string, unknown> } | null;
} | null;

/** The explicit feedback draft. Sending is restricted to the app-owned feedback frame. */
export function feedbackPreview(message: string, email: string, images?: number): { body: import("gpui-kit").HostValue; available: boolean };
/** The clipboard's image, kept for the form (`path` for `image()`); null when it holds none. Frame-only. */
export function feedbackPasteImage(): { path: string } | { error: string } | null;
/** Picks image files (at most 3), each kept like a pasted one. Frame-only. */
export function feedbackPickImages(): Promise<({ path: string } | { error: string })[]>;
/** Attaches dropped image paths (at most 3), using the picker's conversion and limits. Frame-only. */
export function feedbackAttachImages(paths: string[]): ({ path: string } | { error: string })[];
/** Drops the form's kept screenshots. Frame-only. */
export function feedbackClearImages(): null;
export function sendFeedback(body: import("gpui-kit").HostValue, images?: string[]): Promise<string | null>;

/** What the app runs with: the shown layout's look (theme name, fonts, sizes, terminal
 *  padding and opacity) with the person's zoom and sounds. */
export function settings(): Record<string, unknown>;

/** Every key binding: { section, keys, action }. */
export function keys(): { section: string; keys: string; action: string }[];

export interface OverlaySpec {
  /** One mod, or `layout`. */
  mod?: string;
  props?: Record<string, unknown>;
  /** Blocks as in layouts/*.json (`{ terminal: "t7" }` blocks too), instead of `mod`. Its mods get
   *  `props().overlay`. Esc goes to its terminals (agents use it), so give it a way to close.
   *  Closes itself when its terminal ends. */
  layout?: unknown;
  /** dialog: centered, dims the window. popup: at `at` (default: the pointer).
   *  window: stays open until closed (no dimming, a click beside it doesn't close it, Esc goes to
   *  the mod); dragged by any press the mod doesn't stop (`cx.stop_propagation()` on its controls'
   *  mouse down) and stays where dropped; the one pressed last is on top; at `at` (its top left),
   *  else centered; as big as its content unless width/height. It doesn't take the keyboard
   *  when it opens (a mod may focus itself). A layout switch closes windows. */
  kind?: "dialog" | "popup" | "window";
  /** A dialog a click beside it doesn't close (Esc and its own buttons still do). */
  modal?: boolean;
  /** "none": no border, rounded corners, shadow or background around it; the mod draws its own. */
  frame?: "none";
  /** A window's name: it remembers where it was dropped and opens there next time; opening the
   *  same key again replaces the open one, in its place. */
  key?: string;
  /** With `key`: the window also reopens on the next start (and when its layout shows again),
   *  until it's closed. Only the window comes back: a mod keeps its own state (`shared`). */
  keep?: boolean;
  /** px, or up to 1: a share of the window. */
  width?: number;
  height?: number;
  at?: "pointer" | { x: number; y: number };
}

/** Shows a mod (or a layout) above everything. Returns its id. The mod gets `props().overlay` = that id. */
export function openOverlay(spec: OverlaySpec): string;

/** Closes an overlay (mods close themselves with closeOverlay(props().overlay)). Esc closes the top
 *  dialog or popup. A kept window closed this way stays closed. */
export function closeOverlay(id: string): null;

/** Posts a notification. Shown by the `toast` mod (replaceable), which runs `action` when clicked.
 *  Herdr posts one itself when an agent needs you or finished while you weren't looking. Returns its id. */
export function notify(n: {
  title: string;
  body?: string;
  level?: "info" | "success" | "warning" | "error";
  timeout?: number;
  icon?: string;
  action?: { name: string; args?: Record<string, unknown> };
}): string;

/** The props this copy of the mod was given in the layout (or overlay).
 *  A layout's terminal_menu mod gets {tab: "pane", target: {pane: string, terminal: string}, overlay: string}.
 *  Target names the clicked pane/terminal, not necessarily the focused one; pass it to actions.
 *  Close the popup with closeOverlay(props().overlay). */
/** Size is not a prop: root div/h_flex/v_flex.on_size_change reports logical px.
 * The exported View may implement async close(cx) for bounded final cleanup. */
export function props(): any;

/** Reads a value every mod can see (persisted). */
export function shared(key: string): unknown;

/** Sets a shared value; every mod re-renders so it can react. */
export function setShared(key: string, value: unknown): null;

/**
 * Waits for the next key command for this mod ("alt-s": "<mod>:<command>" in keys.json).
 * With "focusable": true in mod.json, pane.go can move onto this copy and send "focus".
 * Focus your own handle then (this.handle.focus()) and handle keys with on_key_down.
 * The copy gets "focus" again when a popup over it closes. Leave with pane.go.
 *   cx.spawn(async (cx) => { for (;;) { const c = await nextCommand(); ...; cx.notify(); } });
 */
export function nextCommand(): Promise<string>;

/**
 * Waits for changes under a folder and returns absolute paths in batches.
 * On Linux, Git-ignored directories and Git's object database are skipped; trees
 * above 4096 non-ignored directories reject the watch, so use a timer fallback.
 * macOS and Windows watch recursively, including ignored directories.
 * Pending paths are bounded: a batch containing the root means refresh everything.
 * Shared by every mod. Files also refreshes on its 10-second timer.
 *   cx.spawn(async (cx) => { for (;;) { await watchFolder(dir); this.reload(); cx.notify(); } });
 * Watch what you show, not a whole home folder (node_modules is a lot of events).
 */
export function watchFolder(path: string): Promise<string[]>;
